/* Life RPG 6.2 Financial OS */
let smartInboxProposals=[];
let aiImportQueue=[];

function validDateKey(s){return /^\d{4}-\d{2}-\d{2}$/.test(String(s||""))}
function addMonthsDate(d,n){const x=new Date(d);const day=x.getDate();x.setDate(1);x.setMonth(x.getMonth()+n);x.setDate(Math.min(day,new Date(x.getFullYear(),x.getMonth()+1,0).getDate()));return x}
function debtEffectiveRate(d){if(Array.isArray(d.parts)&&d.parts.length){const total=d.parts.reduce((s,p)=>s+(+p.balance||0),0);if(total>0)return d.parts.reduce((s,p)=>s+(+p.balance||0)*(+p.rate||0),0)/total}return +d.rate||0}
function debtPaymentAmount(d){return Math.min(+d.balance||0,Math.max(0,+d.nextPaymentAmount||+d.min||0))}
function debtNextDueDate(d,from=new Date()){
  const start=new Date(from.getFullYear(),from.getMonth(),from.getDate(),0,0,0);
  if(validDateKey(d.nextPaymentDate)){const x=parseLocal(d.nextPaymentDate);if(x>=start)return x}
  return null
}
function debtScheduleIssues(){return (S.debts||[]).filter(d=>d.balance>0&&!validDateKey(d.nextPaymentDate))}
function debtEventsBetween(start,end){const out=[];(S.debts||[]).forEach((d,i)=>{if(d.balance<=0)return;let dt=debtNextDueDate(d,start);if(!dt)return;let first=true,guard=0;while(dt<=end&&guard++<6){const mk=localMonthKey(dt),base=first&&+d.nextPaymentAmount>0?+d.nextPaymentAmount:(+d.min||0),paid=paymentToDebtMonth(i,mk),amount=Math.max(0,Math.min(d.balance,base-paid));if(amount>0)out.push({date:new Date(dt),dateKey:localDateKey(dt),type:"payment",kind:"debt",label:d.name,amount,debtIndex:i,debtId:d.id,confirmed:first&&validDateKey(d.nextPaymentDate),estimated:!(first&&validDateKey(d.nextPaymentDate))});dt=addMonthsDate(dt,1);first=false} });return out.sort((a,b)=>a.date-b.date)}
function regularEventsBetween(start,end){const out=[];for(const r of activeRegularPayments()){if(r.mandatory===false)continue;let cur=new Date(start.getFullYear(),start.getMonth(),1,12),guard=0;while(cur<=end&&guard++<6){const dt=regularDueDate(r,cur.getFullYear(),cur.getMonth());if(dt>=start&&dt<=end){const mk=localMonthKey(dt),amount=regularRemaining(r,mk);if(amount>0)out.push({date:dt,dateKey:localDateKey(dt),type:"payment",kind:"regular",label:r.name,amount,regularPaymentId:r.id,confirmed:true,estimated:false})}cur=addMonthsDate(cur,1)}}return out}
function incomeEventsBetween(start,end){const out=[];let cur=new Date(start.getFullYear(),start.getMonth(),1,12),guard=0;while(cur<=end&&guard++<6){const y=cur.getFullYear(),m=cur.getMonth(),last=daysInMonth(cur);for(const ev of (S.settings.incomeEvents||[])){const dt=new Date(y,m,Math.min(ev.day,last),9),received=plannedIncomeReceived(ev,y,m),amount=Math.max(0,(+ev.amount||0)-received);if(dt>=start&&dt<=end&&amount>0)out.push({date:dt,dateKey:localDateKey(dt),type:"income",kind:"income",label:ev.label,amount,confirmed:false,estimated:true})}cur=addMonthsDate(cur,1)}return out}
function projectionLivingPerDay(d){const env=Object.values(S.envelopeLimits||{}).reduce((s,x)=>s+(+x||0),0);if(env>0)return monthlyLivingBudget(d)/Math.max(1,daysInMonth(d));return Math.max(0,+S.settings.dailySpendLimit||0)}
function buildFinancialProjection(days=90,opts={}){days=clamp(Math.round(+days||90),1,180);const start=new Date(),startDay=new Date(start.getFullYear(),start.getMonth(),start.getDate(),12),end=addDays(startDay,days-1),incomeFactor=Math.max(0,opts.incomeFactor==null?100:(+opts.incomeFactor||0))/100,oneOff=Math.max(0,+opts.oneOffExpense||0),extraMonthly=Math.max(0,+opts.extraDebtMonthly||0),floor=Math.max(0,+S.settings.minimumCashFloor||0),events=[...incomeEventsBetween(startDay,end),...debtEventsBetween(startDay,end),...regularEventsBetween(startDay,end)];const by={};for(const e of events)(by[e.dateKey]??=[]).push(e);let balance=operatingCashBalance(),minBalance=balance,minDate=localDateKey(startDay),cashGapDate="",income=0,outflow=0,living=0;const series=[];for(let i=0;i<days;i++){const d=addDays(startDay,i),key=localDateKey(d),dayEvents=by[key]||[];for(const e of dayEvents){if(e.type==="income"){const v=e.amount*incomeFactor;balance+=v;income+=v}else{balance-=e.amount;outflow+=e.amount}}const live=projectionLivingPerDay(d);balance-=live;living+=live;if(i===0&&oneOff>0){balance-=oneOff;outflow+=oneOff}if(extraMonthly>0&&d.getDate()===25){balance-=extraMonthly;outflow+=extraMonthly}if(balance<minBalance){minBalance=balance;minDate=key}if(!cashGapDate&&balance<floor)cashGapDate=key;series.push({date:key,balance})}return {days,start:startDay,end,balanceStart:operatingCashBalance(),endingBalance:balance,minBalance,minDate,cashGapDate,income,outflow,living,series,events:events.sort((a,b)=>a.date-b.date),warnings:[...(accountsModeActive()?[]:["Нет подтверждённого банковского остатка"]),...(debtScheduleIssues().length?[`У ${debtScheduleIssues().length} кредиток не указана следующая дата платежа`]:[]),...((!+S.settings.dailySpendLimit&&!Object.values(S.envelopeLimits||{}).some(x=>+x>0))?["Не задан бюджет повседневных расходов"]:[])]}}
function financialHealthData(){const p=buildFinancialProjection(30),cash=operatingCashBalance(),out30=p.outflow+p.living,liq=out30>0?cash/out30:null,planned=Math.max(0,plannedIncomeForMonth()),debt30=p.events.filter(x=>x.kind==="debt").reduce((s,x)=>s+x.amount,0),burden=planned>0?debt30/planned:null,liquidAssets=(S.assets||[]).filter(a=>a.active!==false&&a.liquid).reduce((s,a)=>s+assetValueById(a.id),0)+(+S.settings.emergencyFundBalance||0),dailyEssential=out30/30,reserveDays=dailyEssential>0?liquidAssets/dailyEssential:null;const verified=(S.accounts||[]).filter(a=>a.verifiedAt).map(a=>(Date.now()-Date.parse(a.verifiedAt))/86400000),fresh=verified.length?Math.max(...verified):null;return {liq,burden,reserveDays,fresh,cash,out30,p}}
function healthBadge(label,value,detail,kind=""){return `<div class="health-item ${kind}"><div class="smallcaps">${label}</div><b>${value}</b><div class="sub">${detail}</div></div>`}
function renderFinancialHealth(){const box=$("financialHealth");if(!box)return;const h=financialHealthData(),liq=h.liq==null?"—":h.liq.toFixed(2)+"×",burden=h.burden==null?"—":pct(h.burden*100,0),reserve=h.reserveDays==null?"—":`${Math.floor(h.reserveDays)} дн.`,fresh=h.fresh==null?"не сверено":`${Math.floor(h.fresh)} дн.`;box.innerHTML=`<div class="health-grid">${healthBadge("Ликвидность",liq,`деньги / потребности 30 дней`,h.liq!=null&&h.liq<1?"bad":"")}${healthBadge("Долговая нагрузка",burden,h.burden==null?"нет плана доходов":"обязательные долги / план дохода",h.burden!=null&&h.burden>.5?"bad":"")}${healthBadge("Ликвидный резерв",reserve,"отдельные ликвидные активы",h.reserveDays!=null&&h.reserveDays<7?"warn":"")}${healthBadge("Свежесть данных",fresh,"с момента последней сверки",h.fresh==null||h.fresh>7?"warn":"")}</div>${h.p.warnings.length?`<div class="notice" style="margin-top:10px">${h.p.warnings.map(escapeHtml).join(" • ")}</div>`:""}`}
function safeSpendCapacity(){const p=buildFinancialProjection(30),complete=!p.warnings.some(x=>/бюджет повседневных/.test(x));if(!complete)return null;return Math.max(0,Math.min(freeCashBalance(),p.minBalance-(+S.settings.minimumCashFloor||0)))}
function decisionEngineData(){const p=buildFinancialProjection(30),overdue=financialEvents().filter(x=>x.overdue),issues=debtScheduleIssues(),free=freeCashBalance(),safe=safeSpendCapacity(),actions=[];if(!accountsModeActive())actions.push({level:"bad",title:"Сверить банковский остаток",meta:"Без точки отсчёта решения по деньгам ненадёжны"});if(issues.length)actions.push({level:"warn",title:`Обновить даты платежей: ${issues.length}`,meta:issues.map(x=>x.name).join(", ")});if(overdue.length)actions.push({level:"bad",title:`Закрыть просроченное ${rub(overdue.reduce((s,x)=>s+x.amount,0))}`,meta:overdue[0].label});if(p.cashGapDate)actions.push({level:"bad",title:`Риск кассового разрыва ${fmtDate(parseLocal(p.cashGapDate))}`,meta:`минимум по прогнозу ${rub(p.minBalance)}`});if(!p.cashGapDate&&free>0){const phase=financialPhase(),target=highestHighInterestDebt()||bestDebt();if(target)actions.push({level:"good",title:`Свободно ${rub(free)} — приоритет ${target.name}`,meta:`фаза: ${phase.name} • ставка ${debtEffectiveRate(target).toFixed(2)}%`})}return {p,overdue,issues,free,safe,actions}}
function renderDecisionEngine(){const box=$("decisionEngine");if(!box)return;const d=decisionEngineData();box.innerHTML=`<div class="decision-kpis"><div><span>Свободно сейчас</span><b>${rub(d.free)}</b></div><div><span>Минимум 30 дней</span><b class="${d.p.minBalance<0?"income-bad":""}">${rub(d.p.minBalance)}</b></div><div><span>Безопасный разовый расход</span><b>${d.safe==null?"нужен бюджет":rub(d.safe)}</b></div></div>${d.actions.length?d.actions.slice(0,4).map(a=>`<div class="decision-row ${a.level}"><b>${escapeHtml(a.title)}</b><div class="sub">${escapeHtml(a.meta)}</div></div>`).join(""):'<div class="empty">Критичных действий по финансовой модели нет.</div>'}`}
function checkCanSpend(){const amount=Math.max(0,+$("decisionSpendAmount")?.value||0),out=$("decisionSpendResult");if(!out)return;const base=decisionEngineData();if(base.safe==null){out.innerHTML='<div class="notice">Сначала задай дневной бюджет или конверты расходов. Без этого проверка будет ложной.</div>';return}const p=buildFinancialProjection(30,{oneOffExpense:amount});const ok=amount<=base.safe&&!p.cashGapDate;out.innerHTML=`<div class="notice ${ok?"good-notice":""}"><b>${ok?"По текущей модели расход помещается":"По текущей модели расход небезопасен"}.</b><br>После расхода минимальный прогнозный остаток: ${rub(p.minBalance)}${p.cashGapDate?` • риск разрыва ${fmtDate(parseLocal(p.cashGapDate))}`:""}.</div>`}
function renderFinancialForecast(){const box=$("financialForecast");if(!box)return;const days=+$("forecastDays")?.value||90,incomeFactor=+$("forecastIncomeFactor")?.value||100,oneOff=+$("forecastOneOff")?.value||0,extraDebtMonthly=+$("forecastExtraDebt")?.value||0,p=buildFinancialProjection(days,{incomeFactor,oneOffExpense:oneOff,extraDebtMonthly});const pts=p.series.filter((x,i)=>i===0||i===p.series.length-1||i%Math.max(1,Math.floor(days/6))===0);box.innerHTML=`<div class="forecast-os-grid"><div class="report-item"><div class="smallcaps">Старт</div><b>${rub(p.balanceStart)}</b></div><div class="report-item"><div class="smallcaps">Конец периода</div><b class="${p.endingBalance<0?"income-bad":""}">${rub(p.endingBalance)}</b></div><div class="report-item"><div class="smallcaps">Минимум</div><b class="${p.minBalance<0?"income-bad":""}">${rub(p.minBalance)}</b><div class="sub">${fmtDate(parseLocal(p.minDate))}</div></div><div class="report-item"><div class="smallcaps">Кассовый разрыв</div><b>${p.cashGapDate?fmtDate(parseLocal(p.cashGapDate)):"нет"}</b></div></div><div class="mini-forecast">${pts.map(x=>`<div><span>${fmtDate(parseLocal(x.date))}</span><b class="${x.balance<0?"income-bad":""}">${rub(x.balance)}</b></div>`).join("")}</div>${p.warnings.length?`<div class="status">Ограничения модели: ${p.warnings.map(escapeHtml).join(" • ")}</div>`:""}`}
function renderFinancialControlCalendar(){const box=$("financialControlCalendar");if(!box)return;const p=buildFinancialProjection(90),events=p.events.slice(0,30);box.innerHTML=events.length?events.map(e=>`<div class="event ${e.type}"><div class="date">${fmtDate(e.date)}</div><div><b>${escapeHtml(e.label)}</b><div class="sub">${e.type==="income"?"ожидаемый доход":e.kind==="debt"?(e.confirmed?"подтверждённый платёж":"оценка по текущему графику"):"регулярное обязательство"}</div></div><b>${e.type==="income"?"+":"−"}${rub(e.amount)}</b></div>`).join(""):'<div class="empty">Нет событий на ближайшие 90 дней. Проверь график доходов и даты платежей.</div>'}

function assetValueById(id){const a=(S.assets||[]).find(x=>x.id===id);if(!a)return 0;let value=+a.verifiedValue||0;if(a.verifiedAt){const t=Date.parse(a.verifiedAt)||0;for(const x of S.assetTransfers||[]){if(x.assetId!==id||eventTs(x)<=t)continue;value+=x.direction==="toAsset"?(+x.amount||0):-(+x.amount||0)}}return Math.max(0,value)}
function totalAssetValue(){return (S.assets||[]).filter(a=>a.active!==false).reduce((s,a)=>s+assetValueById(a.id),0)}
function liquidAssetValue(){return (S.assets||[]).filter(a=>a.active!==false&&a.liquid).reduce((s,a)=>s+assetValueById(a.id),0)}
function availableAssetValue(){return (S.assets||[]).filter(a=>a.active!==false&&a.available).reduce((s,a)=>s+assetValueById(a.id),0)}
function netWorth(){return operatingCashBalance()+totalAssetValue()+(+S.settings.emergencyFundBalance||0)-totalDebt()}
function renderAssets(){const sum=$("netWorthSummary"),list=$("assetList");if(!sum||!list)return;sum.innerHTML=`<div class="money-balance-grid"><div class="money-balance"><div class="smallcaps">Деньги</div><b>${rub(operatingCashBalance())}</b></div><div class="money-balance"><div class="smallcaps">Активы</div><b>${rub(totalAssetValue())}</b></div><div class="money-balance"><div class="smallcaps">Долги</div><b>${rub(totalDebt())}</b></div><div class="money-balance"><div class="smallcaps">Чистый капитал</div><b class="${netWorth()>=0?"income-good":"income-bad"}">${rub(netWorth())}</b></div></div>`;list.innerHTML=(S.assets||[]).filter(a=>a.active!==false).length?(S.assets||[]).filter(a=>a.active!==false).map(a=>`<div class="asset-row"><div><b>${escapeHtml(a.name)}</b><div class="qmeta">${escapeHtml(a.type)} • ${a.liquid?"ликвидный":"неликвидный"}${a.available?" • доступен Money Engine":" • не тратить автоматически"}</div></div><b>${rub(assetValueById(a.id))}</b><button class="btn ghost small" onclick="archiveAsset('${a.id}')">Скрыть</button></div>`).join(""):'<div class="empty">Добавь Инвесткопилку, накопления или другие активы.</div>'}
async function addAsset(){const name=$("assetName")?.value.trim(),value=Math.max(0,+$("assetValue")?.value||0);if(!name){toast("Укажи название актива");return}let a=(S.assets||[]).find(x=>x.active!==false&&x.name.toLowerCase()===name.toLowerCase());const data={name,type:$("assetType")?.value||"Инвестиции",verifiedValue:value,verifiedAt:new Date().toISOString(),liquid:$("assetLiquid")?.value!=="false",available:!!$("assetAvailable")?.checked,active:true};if(a)Object.assign(a,data);else(S.assets??=[]).push({id:uid(),...data});$("assetName").value=$("assetValue").value="";audit("Актив обновлён","asset",`${name}: ${rub(value)}`);await save("Актив сохранён")}
