function matchAssetByDescription(desc){const s=String(desc||"").toLowerCase();return (S.assets||[]).find(a=>a.active!==false&&(s.includes(a.name.toLowerCase())||(a.name.toLowerCase().includes("инвест")&&s.includes("инвесткопил"))))||null}

function accountDeltaAfter(accountId,sinceTs){let n=0;for(const x of S.incomeLogs||[])if((x.accountId||defaultAccountId())===accountId&&eventTs(x)>sinceTs)n+=+x.amount||0;for(const x of S.expenses||[])if((x.accountId||defaultAccountId())===accountId&&eventTs(x)>sinceTs)n-=+x.amount||0;for(const x of S.payments||[])if((x.accountId||defaultAccountId())===accountId&&eventTs(x)>sinceTs)n-=+x.amount||0;for(const x of S.bankTransfers||[]){if(eventTs(x)<=sinceTs)continue;if(x.fromAccountId===accountId)n-=+x.amount||0;if(x.toAccountId===accountId)n+=+x.amount||0;if(x.syncAccountId===accountId&&!x.fromAccountId&&!x.toAccountId)n+=+x.syncEffect||0}for(const x of S.assetTransfers||[]){if(eventTs(x)<=sinceTs||x.accountId!==accountId)continue;n+=x.direction==="fromAsset"?(+x.amount||0):-(+x.amount||0)}for(const x of S.fundTransfers||[]){if(eventTs(x)<=sinceTs)continue;const a=x.accountId||defaultAccountId();if(a!==accountId)continue;n+=x.direction==="fromFund"?(+x.amount||0):-(+x.amount||0)}for(const x of S.cashAdjustments||[]){if(eventTs(x)<=sinceTs)continue;if((x.accountId||defaultAccountId())===accountId)n+=+x.delta||0}return n}
function unifiedTransactions(){const arr=[];for(const x of S.incomeLogs||[])arr.push({kind:"income",id:x.id,date:x.date,dateKey:x.dateKey,amount:+x.amount||0,title:x.source||"Доход",note:x.note||"",account:accountName(x.accountId||defaultAccountId()),category:"Доход"});for(const x of S.expenses||[])arr.push({kind:"expense",id:x.id,date:x.date,dateKey:x.dateKey,amount:-(+x.amount||0),title:x.note||x.category||"Расход",note:x.note||"",account:accountName(x.accountId||defaultAccountId()),category:x.category||"Другое"});for(const x of S.payments||[])arr.push({kind:"payment",id:x.id,date:x.date,dateKey:x.localDate,amount:-(+x.amount||0),title:x.debt||"Платёж по долгу",note:"",account:accountName(x.accountId||defaultAccountId()),category:"Долг"});for(const x of S.bankTransfers||[])arr.push({kind:"transfer",id:x.id,date:x.date,dateKey:x.dateKey,amount:0,title:x.note||"Перевод",note:`${x.fromAccountId?accountName(x.fromAccountId):""}${x.fromAccountId||x.toAccountId?" → ":""}${x.toAccountId?accountName(x.toAccountId):""}${x.amount?` • ${rub(x.amount)}`:""}`,account:x.syncAccountId?accountName(x.syncAccountId):"",category:"Перевод"});for(const x of S.assetTransfers||[])arr.push({kind:"asset_transfer",id:x.id,date:x.date,dateKey:x.dateKey,amount:0,title:x.note||"Перевод в актив",note:`${x.direction==="toAsset"?"Счёт → ":"Актив → "}${escapeHtml((S.assets||[]).find(a=>a.id===x.assetId)?.name||"Актив")} • ${rub(x.amount)}`,account:accountName(x.accountId||defaultAccountId()),category:"Актив"});return arr.sort((a,b)=>(Date.parse(b.date)||Date.parse(`${b.dateKey}T12:00:00`))-(Date.parse(a.date)||Date.parse(`${a.dateKey}T12:00:00`)))}
function deleteJournalTransaction(kind,id){if(kind==="asset_transfer"){const i=(S.assetTransfers||[]).findIndex(x=>x.id===id);if(i<0)return;const x=S.assetTransfers.splice(i,1)[0];S.trash.unshift({kind:"asset_transfer",item:x,date:new Date().toISOString()});return save("Перевод актива удалён")}if(kind==="income")return deleteIncome(id);if(kind==="expense")return deleteExpense(id);if(kind==="payment")return undoPayment(id);if(kind==="transfer")return deleteTransfer(id)}

function remainingMinimumsThisMonth(){const mk=localMonthKey(),start=new Date(),end=new Date(start.getFullYear(),start.getMonth()+1,0,23,59,59);return debtEventsBetween(new Date(start.getFullYear(),start.getMonth(),1,0),end).filter(x=>localMonthKey(x.date)===mk).reduce((s,x)=>s+x.amount,0)}
