function overdueMinimums(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),0),start=addDays(today,-45),events=[...debtEventsBetween(start,today),...regularEventsBetween(start,today)];return events.filter(e=>e.date<today).sort((a,b)=>a.date-b.date)}
function financialEvents(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),0),end=addDays(today,62),events=[...incomeEventsBetween(today,end),...debtEventsBetween(addDays(today,-31),end),...regularEventsBetween(addDays(today,-31),end)];for(const e of events)e.overdue=e.type==="payment"&&e.date<today;return events.filter(e=>e.type==="income"?e.date>=today:(e.overdue||e.date>=today)).sort((a,b)=>a.date-b.date).slice(0,24)}

function saveDebtForm(){const id=$("debtEditId").value||"",name=$("debtName").value.trim(),balance=Math.max(0,+$("debtBalance").value||0),rate=Math.max(0,+$("debtRate").value||0),min=Math.max(0,+$("debtMin").value||0),dueDay=clamp(Math.round(+$("debtDueDay").value||1),1,31),type=$("debtType").value,limit=Math.max(0,+$("debtLimit").value||0),nextPaymentDate=$("debtNextPaymentDate")?.value||"",nextPaymentAmount=Math.max(0,+$("debtNextPaymentAmount")?.value||0),paymentMode=$("debtPaymentMode")?.value||(type==="Кредит"?"fixed":"statement"),rateKnown=!!$("debtRateKnown")?.checked;if(!name){toast("Укажи название долга");return}const data={name,balance,rate,min,dueDay,type,limit,nextPaymentDate,nextPaymentAmount,paymentMode,rateKnown,active:true};if(id){const d=debtById(id);if(!d)return;Object.assign(d,data);audit("Долг изменён","debt",name)}else S.debts.push({id:uid(),initial:balance,priority:S.debts.length+1,parts:[],...data});clearDebtForm();save("Долг сохранён")}
function editDebt(id){const d=debtById(id);if(!d)return;const map={debtEditId:"id",debtName:"name",debtBalance:"balance",debtRate:"rate",debtMin:"min",debtDueDay:"dueDay",debtType:"type",debtLimit:"limit",debtNextPaymentDate:"nextPaymentDate",debtNextPaymentAmount:"nextPaymentAmount",debtPaymentMode:"paymentMode"};for(const [el,k] of Object.entries(map))if($(el))$(el).value=d[k]??"";if($("debtRateKnown"))$("debtRateKnown").checked=d.rateKnown!==false;document.getElementById("debtEditorCard")?.scrollIntoView({behavior:"smooth",block:"center"})}
