function parseMoneyNear(text,labelRe){const re=new RegExp(`(?:${labelRe})[^\\d]{0,45}([0-9][0-9 \\u00A0]*(?:[.,][0-9]{1,2})?)\\s*(?:₽|руб|р\\b)?`,"i"),m=String(text||"").match(re);return m?parseOcrAmount(m[1]):null}
