function extractDebtSnapshot(text){const debt=matchDebtFromText(text),balance=parseMoneyNear(text,"общ(?:ая|ий)\\s+задолженность|задолженность|долг\\s+на"),minWith=parseMoneyNear(text,"минимальн(?:ый|ого)\\s+платеж\\s+с\\s+рассрочк\\w*"),minPay=minWith??parseMoneyNear(text,"минимальн(?:ый|ого)\\s+платеж"),limit=parseMoneyNear(text,"кредитн(?:ый|ого)\\s+лимит"),rateMatch=String(text||"").match(/(\d{1,2}(?:[.,]\d{1,3})?)\s*%\s*(?:годовых)?/i),rate=rateMatch?Number(rateMatch[1].replace(",",".")):null;let date="";const dm=String(text||"").match(/(?:до|оплатить\s+до)\s*(\d{1,2})[.\/-](\d{1,2})(?:[.\/-](\d{2,4}))?/i);if(dm){let y=dm[3]?Number(dm[3]):new Date().getFullYear();if(y<100)y+=2000;date=`${y}-${String(dm[2]).padStart(2,"0")}-${String(dm[1]).padStart(2,"0")}`}return {debtId:debt?.id||"",debtName:debt?.name||"",balance,minPay,limit,rate,date}}
function extractAssetSnapshot(text){const s=String(text||"");let name="";if(/инвесткопил/i.test(s))name="Инвесткопилка";else if(/брокерск/i.test(s))name="Брокерский счёт";if(!name)return null;let amount=parseMoneyNear(s,name==="Инвесткопилка"?"инвесткопилк\\w*":"брокерск\\w*\\s+счет");if(amount==null){const m=s.match(/(?:^|\n)\s*([0-9][0-9 \\u00A0]*(?:[.,]\d{1,2})?)\s*₽/m);amount=m?parseOcrAmount(m[1]):null}return amount!=null?{name,amount}:null}
function classifyFinancialScreenshot(text){const s=String(text||"").toLowerCase().replace(/ё/g,"е");if(/минимальн.*платеж|задолженность|кредитн.*лимит|процентн.*ставк/.test(s))return "debt";if(/инвесткопил|действующ.*стратег|фонд денежного рынка|брокерск.*счет/.test(s))return "asset";const tx=extractScreenshotTransactions(text,{dateKey:localDateKey()});if(tx.length>=2)return "operations";if(extractBankBalance(text))return "balance";if(tx.length)return "operations";return "unknown"}
async function recognizeSmartInbox(files){const list=[...files].slice(0,20),status=$("smartInboxStatus");if(!list.length)return;if(!window.Tesseract){status.innerHTML='<span class="csv-bad">OCR-модуль не загрузился. Нужен интернет.</span>';return}smartInboxProposals=[];let operationCount=0;for(let i=0;i<list.length;i++){const file=list[i];status.textContent=`Разбор ${i+1}/${list.length}: ${file.name}`;try{const r=await Tesseract.recognize(file,"rus+eng"),text=r?.data?.text||"",kind=classifyFinancialScreenshot(text),hash=await hashFile(file),dateKey=file.lastModified?localDateKey(new Date(file.lastModified)):localDateKey();if(kind==="operations"){const items=extractScreenshotTransactions(text,{name:file.name,hash,dateKey,accountId:$("smartInboxAccount")?.value||defaultAccountId()});screenshotImportQueue.push(...items);operationCount+=items.length}else if(kind==="balance"){const b=extractBankBalance(text);if(b)smartInboxProposals.push({id:uid(),kind:"balance",file:file.name,amount:b.amount,label:b.label,accountId:$("smartInboxAccount")?.value||defaultAccountId(),confidence:b.confidence})}else if(kind==="debt")smartInboxProposals.push({id:uid(),kind:"debt",file:file.name,...extractDebtSnapshot(text)});else if(kind==="asset"){const a=extractAssetSnapshot(text);smartInboxProposals.push({id:uid(),kind:"asset",file:file.name,...(a||{})})}else smartInboxProposals.push({id:uid(),kind:"unknown",file:file.name})}catch(e){smartInboxProposals.push({id:uid(),kind:"unknown",file:file.name,error:String(e.message||e)})}}renderSmartInbox();if(operationCount){renderScreenshotQueue();$("screenshotImportStatus").innerHTML=`Из универсального входа найдено операций: <b>${operationCount}</b>. Проверь их в Bank Sync ниже.`}status.textContent=`Разобрано файлов: ${list.length}. Операций: ${operationCount}, предложений: ${smartInboxProposals.length}.`}
function renderSmartInbox(){const box=$("smartInboxResults");if(!box)return;box.innerHTML=smartInboxProposals.length?smartInboxProposals.map(p=>{if(p.kind==="balance")return `<div class="smart-proposal"><div><b>Баланс • ${escapeHtml(p.file)}</b><div class="sub">${escapeHtml(accountName(p.accountId))}: ${rub(p.amount)} • уверенность ${Math.round((p.confidence||0)*100)}%</div></div><button class="btn secondary small" onclick="applySmartProposal('${p.id}')">Открыть сверку</button></div>`;if(p.kind==="debt")return `<div class="smart-proposal"><div><b>Долг • ${escapeHtml(p.debtName||"не удалось сопоставить")}</b><div class="sub">${p.balance!=null?`остаток ${rub(p.balance)} • `:""}${p.minPay!=null?`платёж ${rub(p.minPay)} • `:""}${p.date?`до ${fmtDate(parseLocal(p.date))} • `:""}${p.rate!=null?`${p.rate}%`:""}</div></div><button class="btn secondary small" onclick="applySmartProposal('${p.id}')" ${p.debtId?"":"disabled"}>Применить</button></div>`;if(p.kind==="asset")return `<div class="smart-proposal"><div><b>Актив • ${escapeHtml(p.name||"не распознан")}</b><div class="sub">${p.amount!=null?rub(p.amount):"сумма не найдена"}</div></div><button class="btn secondary small" onclick="applySmartProposal('${p.id}')" ${p.name&&p.amount!=null?"":"disabled"}>Применить</button></div>`;return `<div class="smart-proposal"><div><b>Не удалось определить • ${escapeHtml(p.file)}</b><div class="sub">Можно разобрать через AI Bridge.</div></div></div>`}).join(""):''}
