async function handleAiImportFile(file){try{const obj=JSON.parse(await file.text());if(obj.format!=="life-rpg-ai-import-v1"||!Array.isArray(obj.actions))throw new Error("Неверный формат пакета");aiImportQueue=obj.actions.map((a,i)=>({id:a.id||`a${i+1}`,include:a.include!==false,...a}));renderAiImportPreview();$("aiImportStatus").textContent=`Загружено действий: ${aiImportQueue.length}`;$("aiApplyBtn").disabled=!aiImportQueue.length}catch(e){$("aiImportStatus").innerHTML=`<span class="csv-bad">${escapeHtml(e.message||String(e))}</span>`;aiImportQueue=[];renderAiImportPreview();$("aiApplyBtn").disabled=true}}
