function renderFinancialHealth(){const box=$("financialHealth");if(!box)return;const h=financialHealthData(),target=Math.max(1,+S.settings.liquidityTargetDays||14),liq=h.liq==null?"—":h.liq.toFixed(2)+"×",burden=h.burden==null?"—":pct(h.burden*100,0),reserve=h.reserveDays==null?"—":`${Math.floor(h.reserveDays)} дн.`,fresh=h.fresh==null?"не сверено":`${Math.floor(h.fresh)} дн.`;box.innerHTML=`<div class="health-grid">${healthBadge("Ликвидность",liq,"деньги / потребности 30 дней",h.liq!=null&&h.liq<1?"bad":"")}${healthBadge("Долговая нагрузка",burden,h.burden==null?"нет плана доходов":"обязательные долги / план дохода",h.burden!=null&&h.burden>.5?"bad":"")}${healthBadge("Ликвидный резерв",reserve,`цель ${target} дней • не считается обычными деньгами`,h.reserveDays!=null&&h.reserveDays<target?"warn":"")}${healthBadge("Свежесть данных",fresh,"с момента последней сверки",h.fresh==null||h.fresh>7?"warn":"")}</div>${h.p.warnings.length?`<div class="notice" style="margin-top:10px">${h.p.warnings.map(escapeHtml).join(" • ")}</div>`:""}`}
function decisionEngineData(){const p=buildFinancialProjection(30),overdue=financialEvents().filter(x=>x.overdue),issues=debtScheduleIssues(),free=freeCashBalance(),safe=safeSpendCapacity(),availableReserve=availableAssetValue()+(+S.settings.emergencyFundBalance||0),actions=[];if(!accountsModeActive())actions.push({level:"bad",title:"Сверить банковский остаток",meta:"Без точки отсчёта решения по деньгам ненадёжны"});if(issues.length)actions.push({level:"warn",title:`Обновить даты платежей: ${issues.length}`,meta:issues.map(x=>x.name).join(", ")});if(overdue.length)actions.push({level:"bad",title:`Закрыть просроченное ${rub(overdue.reduce((ss,x)=>ss+x.amount,0))}`,meta:overdue[0].label});if(p.cashGapDate){actions.push({level:"bad",title:`Риск кассового разрыва ${fmtDate(parseLocal(p.cashGapDate))}`,meta:`минимум по прогнозу ${rub(p.minBalance)}`});if(availableReserve>0)actions.push({level:"warn",title:`Есть резерв ${rub(availableReserve)}`,meta:"Он не считается обычными деньгами; использовать только после отдельного решения"})}if(!p.cashGapDate&&free>0){const phase=financialPhase(),target=highestHighInterestDebt()||bestDebt();if(target)actions.push({level:"good",title:`Свободно ${rub(free)} — приоритет ${target.name}`,meta:`фаза: ${phase.name} • ставка ${debtEffectiveRate(target).toFixed(2)}%`})}return {p,overdue,issues,free,safe,availableReserve,actions}}

function matchDebtPaymentCandidate(desc,amount=0){const s=String(desc||"").toLowerCase().replace(/ё/g,"е"),open=(S.debts||[]).filter(d=>d.balance>0);let c=open;if(/платинум|platinum/.test(s))c=open.filter(d=>/платин/i.test(d.name));else if(/райфф/.test(s))c=open.filter(d=>/райфф/i.test(d.name));else if(/альфа/.test(s))c=open.filter(d=>/альфа/i.test(d.name));else if(/т.?банк|тинькофф/.test(s)&&/кредит/.test(s))c=open.filter(d=>/т.?банк|тинькофф/i.test(d.name));if(c.length===1)return c[0];if(amount>0){const ranked=open.map(d=>({d,delta:Math.min(Math.abs((+d.nextPaymentAmount||0)-amount),Math.abs((+d.min||0)-amount))})).sort((a,b)=>a.delta-b.delta);if(ranked[0]&&ranked[0].delta<=Math.max(10,amount*.03)&&(ranked.length<2||ranked[1].delta>ranked[0].delta+1))return ranked[0].d}return null}
function refineFinancialCandidate(c){const s=String(c.desc||"").toLowerCase().replace(/ё/g,"е");if(/досрочн.*погашен|погашен.*кредит|плат[её]ж.*(?:по\s+)?кредит/.test(s)){const d=matchDebtPaymentCandidate(c.desc,c.amount);return {...c,type:"debt_payment",suggestedType:"debt_payment",debtId:d?.id||"",confidence:Math.max(c.confidence||0,.86)}}if(/инвесткопил|брокерск.*счет|брокерск.*счёт/.test(s)){const a=matchAssetByDescription(c.desc);return {...c,type:"asset_transfer",suggestedType:"asset_transfer",assetId:a?.id||"",confidence:Math.max(c.confidence||0,.86)}}return c}
function screenshotTypeOptions(v){return [["expense","Расход"],["income","Доход"],["transfer","Между своими счетами"],["asset_transfer","Перевод актив ↔ счёт"],["debt_payment","Платёж по долгу"],["ignore","Не импортировать"]].map(([x,t])=>`<option value="${x}" ${x===v?"selected":""}>${t}</option>`).join("")}
function candidateSyncEffect(c){const a=Math.max(0,+c.amount||0);if(c.type==="income")return a;if(c.type==="expense"||c.type==="debt_payment")return -a;if(c.type==="asset_transfer"||c.type==="transfer")return c.ocrSign==="+"?a:(c.ocrSign==="-"?-a:0);return 0}
